//! Anti-aliased fonts: glyph lookup, text width and colour blending. Pure and host-testable; the
//! coverage data comes from `fontdata` (generated by `tools/genfont.py`).

use crate::fontdata::{self as d, GlyphData};

/// One glyph ready to draw: a `w` x `h` bitmap of 0..=255 coverage in `cov`, `left` pixels right of
/// the pen and `top` pixels above the baseline; the pen moves `advance` pixels afterwards.
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    pub advance: u8,
    pub w: u8,
    pub h: u8,
    pub left: i8,
    pub top: i8,
    pub cov: &'static [u8],
}

/// A font at one pixel size.
#[derive(Clone, Copy, Debug)]
pub struct Face {
    pub size: u8,
    /// Pixels from the top of a line to the baseline.
    pub ascent: u8,
    /// Line height in pixels.
    pub height: u8,
    codes: &'static [u8],
    glyphs: &'static [GlyphData],
    cov: &'static [u8],
}

pub static SANS_16: Face = Face {
    size: d::SANS_16_SIZE,
    ascent: d::SANS_16_ASCENT,
    height: d::SANS_16_HEIGHT,
    codes: &d::SANS_16_CODES,
    glyphs: &d::SANS_16_GLYPHS,
    cov: &d::SANS_16_COV,
};

pub static SANS_24: Face = Face {
    size: d::SANS_24_SIZE,
    ascent: d::SANS_24_ASCENT,
    height: d::SANS_24_HEIGHT,
    codes: &d::SANS_24_CODES,
    glyphs: &d::SANS_24_GLYPHS,
    cov: &d::SANS_24_COV,
};

/// The big "AEON" lettering. Only those four letters exist; anything else draws as nothing.
pub static WORDMARK: Face = Face {
    size: d::WORDMARK_SIZE,
    ascent: d::WORDMARK_ASCENT,
    height: d::WORDMARK_HEIGHT,
    codes: &d::WORDMARK_CODES,
    glyphs: &d::WORDMARK_GLYPHS,
    cov: &d::WORDMARK_COV,
};

/// Fixed-width face for the shell: every glyph advances `MONO_CELL.0` pixels.
pub static MONO: Face = Face {
    size: d::MONO_SIZE,
    ascent: d::MONO_ASCENT,
    height: d::MONO_HEIGHT,
    codes: &d::MONO_CODES,
    glyphs: &d::MONO_GLYPHS,
    cov: &d::MONO_COV,
};

/// The larger fixed-width face, used on screens 1600 pixels wide or more.
pub static MONO_L: Face = Face {
    size: d::MONO_L_SIZE,
    ascent: d::MONO_L_ASCENT,
    height: d::MONO_L_HEIGHT,
    codes: &d::MONO_L_CODES,
    glyphs: &d::MONO_L_GLYPHS,
    cov: &d::MONO_L_COV,
};

/// Width and height of one shell character cell.
pub const MONO_CELL: (usize, usize) = (d::MONO_CELL_W as usize, d::MONO_CELL_H as usize);
/// Cell size of [`MONO_L`].
pub const MONO_L_CELL: (usize, usize) = (d::MONO_L_CELL_W as usize, d::MONO_L_CELL_H as usize);

const EMPTY: Glyph = Glyph { advance: 0, w: 0, h: 0, left: 0, top: 0, cov: &[] };

impl Face {
    fn index(&self, code: u8) -> Option<usize> {
        self.codes.binary_search(&code).ok()
    }

    fn make(&self, i: usize) -> Glyph {
        let g = &self.glyphs[i];
        let start = g.off as usize;
        let len = g.w as usize * g.h as usize;
        Glyph { advance: g.advance, w: g.w, h: g.h, left: g.left, top: g.top, cov: self.cov.get(start..start + len).unwrap_or(&[]) }
    }
}

/// The glyph for `ch`. Characters the face does not have give `?` if it has one, otherwise an empty
/// glyph with no advance. Never fails.
pub fn glyph(face: &Face, ch: char) -> Glyph {
    let code = u8::try_from(u32::from(ch)).ok().filter(|c| (0x20..0x7F).contains(c));
    if let Some(i) = code.and_then(|c| face.index(c)) {
        return face.make(i);
    }
    match face.index(b'?') {
        Some(i) => face.make(i),
        None => EMPTY,
    }
}

/// Pixel width of `s` set in `face`.
pub fn text_width(face: &Face, s: &str) -> usize {
    s.chars().map(|c| glyph(face, c).advance as usize).sum()
}

/// Blends `fg` over `bg` (both `0x00RRGGBB`) with `coverage` 0..=255.
pub fn blend(bg: u32, fg: u32, coverage: u8) -> u32 {
    let a = coverage as u32;
    let mix = |shift: u32| {
        let b = (bg >> shift) & 0xFF;
        let f = (fg >> shift) & 0xFF;
        // Rounded: (b * (255 - a) + f * a) / 255.
        (b * (255 - a) + f * a + 127) / 255
    };
    (mix(16) << 16) | (mix(8) << 8) | mix(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    const FACES: [&Face; 5] = [&SANS_16, &SANS_24, &WORDMARK, &MONO, &MONO_L];

    #[test]
    fn codes_are_sorted_and_unique_so_lookup_finds_every_glyph() {
        for f in FACES {
            assert!(f.codes.windows(2).all(|w| w[0] < w[1]));
            assert_eq!(f.codes.len(), f.glyphs.len());
            for &c in f.codes {
                assert!(f.index(c).is_some(), "{c}");
            }
        }
        for c in "AEON".chars() {
            assert!(glyph(&WORDMARK, c).w > 0, "{c}");
        }
    }

    #[test]
    fn unknown_char_gives_question_mark_glyph() {
        let q = glyph(&SANS_16, '?');
        for ch in ['é', '日', '\u{0}', '\u{7f}', '\u{1F600}'] {
            let g = glyph(&SANS_16, ch);
            assert_eq!((g.advance, g.w, g.h), (q.advance, q.w, q.h), "{ch:?}");
        }
    }

    #[test]
    fn face_without_question_mark_gives_empty_glyph() {
        let g = glyph(&WORDMARK, 'x');
        assert_eq!((g.advance, g.w, g.h), (0, 0, 0));
        assert!(glyph(&WORDMARK, 'A').w > 0);
    }

    #[test]
    fn width_is_sum_of_advances() {
        let w = text_width(&SANS_16, "Aeon");
        let sum: usize = "Aeon".chars().map(|c| glyph(&SANS_16, c).advance as usize).sum();
        assert_eq!(w, sum);
        assert!(w > 0);
    }

    #[test]
    fn empty_text_has_zero_width() {
        for f in FACES {
            assert_eq!(text_width(f, ""), 0);
        }
    }

    #[test]
    fn mono_glyphs_share_one_advance() {
        let a = glyph(&MONO, 'i').advance;
        for c in ['M', 'W', ' ', '.', 'g'] {
            assert_eq!(glyph(&MONO, c).advance, a);
        }
        assert_eq!(a as usize, MONO_CELL.0);
        assert_eq!(glyph(&MONO_L, 'M').advance as usize, MONO_L_CELL.0);
        assert_eq!(glyph(&MONO_L, 'i').advance as usize, MONO_L_CELL.0);
    }

    #[test]
    fn glyph_coverage_len_matches_w_times_h() {
        for f in FACES {
            for ch in (0x20u8..0x7F).map(char::from) {
                let g = glyph(f, ch);
                assert_eq!(g.cov.len(), g.w as usize * g.h as usize, "{ch:?}");
            }
        }
    }

    #[test]
    fn letters_have_ink_and_space_has_none() {
        assert!(glyph(&SANS_24, 'A').cov.iter().any(|&c| c > 200));
        assert_eq!(glyph(&SANS_24, ' ').w, 0);
        assert!(glyph(&SANS_24, ' ').advance > 0);
    }

    #[test]
    fn blend_endpoints_and_midpoint() {
        assert_eq!(blend(0x102030, 0xFFFFFF, 0), 0x102030);
        assert_eq!(blend(0x102030, 0xFFEEDD, 255), 0xFFEEDD);
        let m = blend(0x000000, 0xFFFFFF, 128);
        for shift in [16, 8, 0] {
            let c = ((m >> shift) & 0xFF) as i32;
            assert!((c - 128).abs() <= 1, "{c}");
        }
        // The top byte is never touched.
        assert_eq!(blend(0, 0xFFFFFF, 255) >> 24, 0);
    }
}
